        "testata": "Politico",
        "lingua_originale": "en",
        "titolo_orig": "Trump plays Texas hold ’em with Senate endorsement",
        "testo_it": "Donald Trump celebra il sostegno del Senato durante la conferenza CPAC in Texas.",
        "priorita": "Bassa",
        "id_gruppo": 1,
        "link": "https://www.politico.com/news/2026/03/27/trump-texas-senate-endorsement-00847967",
